<?php

namespace Microsoft\BingAds\V13\CampaignManagement;

{
    /**
     * Defines AI Max settings for a Search campaign.
     * @link https:/learn.microsoft.com/advertising/campaign-management-service/aisearchsetting?view=bingads-13 AISearchSetting Data Object
     */
    final class AISearchSetting extends Setting
    {
        /**
         * Determines whether AI Max is enabled.
         * @var boolean
         */
        public $AISearchEnabled;

        /**
         * Determines whether to opt out of auto-generated images.
         * @var boolean
         */
        public $AutoGeneratedImageOptOut;

        /**
         * Determines whether to opt out of auto-generated text.
         * @var boolean
         */
        public $AutoGeneratedTextOptOut;

        /**
         * Determines whether to opt out of final URL expansion.
         * @var boolean
         */
        public $FinalUrlExpansionOptOut;

        /**
         * The unique page feed identifiers to associate with AI Max.
         * @var integer[]
         */
        public $PageFeedIds;

        /**
         * Determines whether to opt out of search term matching.
         * @var boolean
         */
        public $SearchTermMatchingOptOut;
    }

}
